import{_ as a,o as l,c as o,ag as s}from"./chunks/framework.CrXGS008.js";const g=JSON.parse('{"title":"Túneles","description":"","frontmatter":{},"headers":[],"relativePath":"es/car-wash/tunnels.md","filePath":"es/car-wash/tunnels.md"}'),r={name:"es/car-wash/tunnels.md"};function n(t,e,i,c,d,u){return l(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="tuneles" tabindex="-1">Túneles <a class="header-anchor" href="#tuneles" aria-label="Permalink to &quot;Túneles&quot;">​</a></h1><p>Un túnel es una entrada donde se detiene el conductor, una línea que sigue el vehículo, y los arcos, cepillos y el secador colocados a lo largo de ella. Hay dos túneles listos para usar: <strong>Strawberry</strong> y <strong>Little Seoul</strong>.</p><h2 id="como-es-un-lavado" tabindex="-1">Cómo es un lavado <a class="header-anchor" href="#como-es-un-lavado" aria-label="Permalink to &quot;Cómo es un lavado&quot;">​</a></h2><ol><li>El conductor se detiene en la entrada, mirando hacia la salida. Un aviso muestra el precio más bajo.</li><li><strong>E</strong> abre el menú de lavado con los programas y sus precios (descuentos por trabajo y porcentaje del túnel incluidos).</li><li>Se paga el precio y el vehículo se guía a lo largo de la línea: jabón, cepillos, aclarado, secador, según el programa. Todos los que están cerca ven el mismo lavado.</li><li>A la salida, el vehículo está limpio, y encerado si el programa incluye cera.</li></ol><p>La entrada rechaza el lavado cuando:</p><ul><li>el túnel ya está en uso (un vehículo cada vez);</li><li>el vehículo va en sentido contrario;</li><li>otro vehículo bloquea el carril;</li><li>la clase del vehículo está bloqueada, o el vehículo es demasiado ancho (<code>BlockedClasses</code>, <code>MaxVehicleWidth</code>);</li><li>el vehículo ya está limpio y <code>RequireDirt</code> está activado;</li><li>el jugador no puede pagar.</li></ul><h2 id="el-editor-de-tuneles" tabindex="-1">El editor de túneles <a class="header-anchor" href="#el-editor-de-tuneles" aria-label="Permalink to &quot;El editor de túneles&quot;">​</a></h2><p>Ábrelo con <code>/nay:carwash</code>, o con <strong>Gestionar túneles</strong> en la página Car Wash de <code>/nay</code>. Necesita el scope <code>nay_car_wash.config</code>.</p><p>El gestor lista los túneles: ir a uno, editarlo, abrirlo o cerrarlo, eliminarlo. Para añadir uno:</p><ol><li><p><strong>Crear aquí</strong>: colócate en la entrada, mirando hacia la salida. O <strong>Copiar</strong> uno de los lavaderos del juego base.</p></li><li><p>Elige un elemento (entrada, inicio y fin de línea, arcos, cepillos, secador) y muévelo con los botones o con el teclado:</p><ul><li>flechas: adelante, atrás, izquierda, derecha a lo largo del carril;</li><li>Re Pág / Av Pág (Page Up / Page Down): altura;</li><li>Q / E: girar;</li><li>Tab: siguiente elemento.</li></ul><p>Hay tres tamaños de paso para los ajustes finos.</p></li><li><p><strong>A mi posición</strong> y <strong>Al suelo</strong> recolocan el elemento seleccionado. <strong>Moverse</strong> (G) libera el ratón para que puedas desplazarte y mirar. Pulsa G otra vez para recuperar el panel.</p></li><li><p><strong>Guardar túnel</strong>. El túnel queda activo para todos los jugadores al instante.</p></li></ol><p>El editor rellena el ajuste <code>Tunnels</code>. Sus campos se describen en la página <a href="/es/car-wash/settings#tuneles">Ajustes</a>.</p>',11)])])}const h=a(r,[["render",n]]);export{g as __pageData,h as default};
